ALTER TABLE public.siddi_owner_setup ADD COLUMN invitation_started_at timestamptz;
CREATE OR REPLACE FUNCTION public.claim_owner_invitation() RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.siddi_owner_setup; BEGIN SELECT * INTO s FROM public.siddi_owner_setup WHERE id=true FOR UPDATE; IF s.owner_email IS NULL OR s.completed_at IS NOT NULL OR (s.invitation_started_at IS NOT NULL AND s.invitation_started_at>now()-interval '15 minutes') THEN RAISE EXCEPTION 'Setup invitation unavailable'; END IF; UPDATE public.siddi_owner_setup SET invitation_started_at=now() WHERE id=true; RETURN s.owner_email; END $$;
REVOKE ALL ON FUNCTION public.claim_owner_invitation() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_owner_invitation() TO service_role;
CREATE OR REPLACE FUNCTION public.admin_provision_account(_user uuid,_role text,_profile jsonb,_actor uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF NOT public.has_role(_actor,'admin') OR _role NOT IN ('admin','supervisor','field_worker') THEN RAISE EXCEPTION 'Provisioning not permitted'; END IF;
 IF _role='admin' AND NOT public.can_manage_admins(_actor) THEN RAISE EXCEPTION 'Administrator creation not delegated'; END IF;
 IF _role<>'admin' AND (coalesce(jsonb_array_length(_profile->'categories'),0)=0 OR NOT EXISTS(SELECT 1 FROM public.civic_teams t WHERE t.active AND t.department=_profile->>'department')) THEN RAISE EXCEPTION 'Configured department and categories required'; END IF;
 INSERT INTO public.user_roles(user_id,role) VALUES(_user,_role::public.app_role);
 INSERT INTO public.staff_profiles(user_id,display_name,designation,department,categories,wards,team_ids,corporations,created_by,updated_by) VALUES(_user,_profile->>'fullName',_profile->>'designation',_profile->>'department',ARRAY(SELECT jsonb_array_elements_text(_profile->'categories')),ARRAY(SELECT jsonb_array_elements_text(_profile->'wards')),ARRAY(SELECT jsonb_array_elements_text(_profile->'teamIds'))::uuid[],ARRAY(SELECT jsonb_array_elements_text(_profile->'corporations')),_actor,_actor);
 IF _role='admin' THEN INSERT INTO public.admin_permissions(user_id,created_by) VALUES(_user,_actor); END IF;
 INSERT INTO public.civic_directory_audit(table_name,record_id,action,actor_id,new_row) VALUES('staff_accounts',_user,'invited',_actor,jsonb_build_object('role',_role,'department',_profile->>'department'));
END $$;
REVOKE ALL ON FUNCTION public.admin_provision_account(uuid,text,jsonb,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.admin_provision_account(uuid,text,jsonb,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.admin_change_role(_user uuid,_role text,_grant boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF NOT public.has_role(auth.uid(),'admin') OR _user=auth.uid() OR _role NOT IN ('admin','supervisor','field_worker','staff') THEN RAISE EXCEPTION 'Role change not permitted'; END IF;
 IF EXISTS(SELECT 1 FROM public.admin_permissions WHERE user_id=_user AND is_super_admin) THEN RAISE EXCEPTION 'Super Admin ownership is protected'; END IF;
 IF (_role='admin' OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user AND role='admin')) AND NOT public.can_manage_admins(auth.uid()) THEN RAISE EXCEPTION 'Administrator management not delegated'; END IF;
 IF _grant THEN INSERT INTO public.user_roles(user_id,role) VALUES(_user,_role::public.app_role) ON CONFLICT DO NOTHING; ELSE DELETE FROM public.user_roles WHERE user_id=_user AND role::text=_role; END IF;
 INSERT INTO public.civic_directory_audit(table_name,record_id,action,actor_id,new_row) VALUES('staff_accounts',_user,'role_changed',auth.uid(),jsonb_build_object('role',_role,'granted',_grant));
END $$;
REVOKE ALL ON FUNCTION public.admin_change_role(uuid,text,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_change_role(uuid,text,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.admin_set_staff_profile(_user uuid,_name text,_designation text,_department text,_categories text[],_wards text[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF NOT public.has_role(auth.uid(),'admin') OR (EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user AND role='admin') AND NOT public.can_manage_admins(auth.uid())) THEN RAISE EXCEPTION 'Profile change not permitted'; END IF;
 IF EXISTS(SELECT 1 FROM public.admin_permissions WHERE user_id=_user AND is_super_admin) THEN RAISE EXCEPTION 'Owner profile is protected'; END IF;
 IF cardinality(_categories)=0 OR NOT EXISTS(SELECT 1 FROM public.civic_teams WHERE active AND department=_department) THEN RAISE EXCEPTION 'Configured department and categories required'; END IF;
 UPDATE public.staff_profiles SET display_name=trim(_name),designation=trim(_designation),department=_department,categories=_categories,wards=_wards,updated_by=auth.uid(),updated_at=now() WHERE user_id=_user;
 INSERT INTO public.civic_directory_audit(table_name,record_id,action,actor_id,new_row) VALUES('staff_accounts',_user,'scope_changed',auth.uid(),jsonb_build_object('department',_department,'categories',_categories,'wards',_wards));
END $$;
CREATE OR REPLACE FUNCTION public.admin_set_team_scope(_user uuid,_teams uuid[],_corporations text[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.staff_profiles; BEGIN
 IF NOT public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user AND role='admin') THEN RAISE EXCEPTION 'Operational scope change not permitted'; END IF;
 SELECT * INTO p FROM public.staff_profiles WHERE user_id=_user;
 IF EXISTS(SELECT 1 FROM unnest(_teams) a WHERE NOT EXISTS(SELECT 1 FROM public.civic_teams t WHERE t.id=a AND t.active AND t.department=p.department AND p.categories<@t.categories)) THEN RAISE EXCEPTION 'Team must match department and category scope'; END IF;
 UPDATE public.staff_profiles SET team_ids=_teams,corporations=_corporations,updated_by=auth.uid(),updated_at=now() WHERE user_id=_user;
 INSERT INTO public.civic_directory_audit(table_name,record_id,action,actor_id,new_row) VALUES('staff_accounts',_user,'team_scope_changed',auth.uid(),jsonb_build_object('team_ids',_teams,'corporations',_corporations));
END $$;
REVOKE ALL ON FUNCTION public.admin_set_team_scope(uuid,uuid[],text[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_set_team_scope(uuid,uuid[],text[]) TO authenticated;
CREATE TABLE public.notification_reads (notification_id uuid NOT NULL REFERENCES public.issue_notifications(id) ON DELETE CASCADE,user_id uuid NOT NULL,read_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(notification_id,user_id));
GRANT SELECT,INSERT ON public.notification_reads TO authenticated;
GRANT ALL ON public.notification_reads TO service_role;
ALTER TABLE public.notification_reads ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own notification reads" ON public.notification_reads FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.is_staff(auth.uid()));
CREATE POLICY "authorized notification mark" ON public.notification_reads FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.issue_notifications n WHERE n.id=notification_id AND public.staff_can_work(auth.uid(),n.issue_id)));
CREATE OR REPLACE FUNCTION public.record_issue_notification() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF NEW.kind='created' THEN INSERT INTO public.issue_notifications(issue_id,audience,channel,status,detail) VALUES(NEW.issue_id,'authority','none','not_configured','No authorized external government channel is configured. Report is persisted in Siddi; no government delivery recorded.');
 ELSIF NEW.kind IN ('acknowledged','eta_changed','status_change') THEN INSERT INTO public.issue_notifications(issue_id,audience,channel,status,detail,attempts) VALUES(NEW.issue_id,'citizen','in_app','posted','Latest persisted case update is available on citizen tracking.',1); END IF;
 IF NEW.kind IN ('created','assignment','acknowledged','eta_changed','status_change','escalated','ack_escalated','duplicate_merge','evidence_completion','citizen_reopened','citizen_confirmed','reopened') THEN INSERT INTO public.issue_notifications(issue_id,audience,channel,status,detail,attempts) VALUES(NEW.issue_id,'supervisor','in_app','posted',NEW.kind||': '||left(coalesce(NEW.note,'Case updated'),250),1); END IF;
 RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION public.civic_case_metrics() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN
 IF NOT public.is_staff(auth.uid()) THEN RAISE EXCEPTION 'Active portal access required'; END IF;
 WITH scoped AS(SELECT * FROM public.issues WHERE public.staff_can_work(auth.uid(),id)) SELECT jsonb_build_object('total_reports',count(*),'canonical_issues',count(*) FILTER(WHERE duplicate_of IS NULL),'pending',count(*) FILTER(WHERE duplicate_of IS NULL AND status::text NOT IN ('resolved','closed','rejected')),'resolved',count(*) FILTER(WHERE duplicate_of IS NULL AND status::text IN ('resolved','closed')),'citizen_confirmed',count(*) FILTER(WHERE duplicate_of IS NULL AND EXISTS(SELECT 1 FROM public.issue_events e WHERE e.issue_id=scoped.id AND e.kind='citizen_confirmed')),'overdue',count(*) FILTER(WHERE duplicate_of IS NULL AND status::text NOT IN ('resolved','closed','rejected') AND (sla_due_at<now() OR eta_at<now())),'awaiting_ack',count(*) FILTER(WHERE duplicate_of IS NULL AND acknowledged_at IS NULL AND status::text NOT IN ('resolved','closed','rejected')),'assigned_to_me',count(*) FILTER(WHERE assigned_to=auth.uid() AND status::text NOT IN ('resolved','closed','rejected')),'in_progress',count(*) FILTER(WHERE duplicate_of IS NULL AND status='in_progress'),'awaiting_review',count(*) FILTER(WHERE duplicate_of IS NULL AND status='awaiting_verification'),'unassigned',count(*) FILTER(WHERE duplicate_of IS NULL AND team_id IS NULL AND status::text NOT IN ('resolved','closed','rejected')),'routing_exceptions',count(*) FILTER(WHERE assignment_state='routing_exception' AND status::text NOT IN ('resolved','closed','rejected')),'duplicate_reviews',count(*) FILTER(WHERE duplicate_candidate_id IS NOT NULL),'reopened',count(*) FILTER(WHERE duplicate_of IS NULL AND status='reopened'),'average_ack_hours',avg(extract(epoch FROM acknowledged_at-created_at)/3600) FILTER(WHERE acknowledged_at IS NOT NULL),'average_resolution_hours',avg(extract(epoch FROM resolved_at-created_at)/3600) FILTER(WHERE duplicate_of IS NULL AND resolved_at IS NOT NULL),'duplicate_rate',CASE WHEN count(*)=0 THEN 0 ELSE round(100.0*count(*) FILTER(WHERE duplicate_of IS NOT NULL)/count(*),2) END,'resolution_rate',CASE WHEN count(*) FILTER(WHERE duplicate_of IS NULL)=0 THEN 0 ELSE round(100.0*count(*) FILTER(WHERE duplicate_of IS NULL AND status::text IN ('resolved','closed'))/count(*) FILTER(WHERE duplicate_of IS NULL),2) END) INTO result FROM scoped;
 RETURN result||jsonb_build_object('status_distribution',(SELECT coalesce(jsonb_object_agg(status,n),'{}') FROM(SELECT status,count(*) n FROM public.issues WHERE public.staff_can_work(auth.uid(),id) AND duplicate_of IS NULL GROUP BY status)s),'category_distribution',(SELECT coalesce(jsonb_object_agg(category,n),'{}') FROM(SELECT category,count(*) n FROM public.issues WHERE public.staff_can_work(auth.uid(),id) AND duplicate_of IS NULL GROUP BY category)s),'department_workload',(SELECT coalesce(jsonb_object_agg(department,n),'{}') FROM(SELECT coalesce(t.department,i.department,'Routing required') department,count(*) n FROM public.issues i LEFT JOIN public.civic_teams t ON t.id=i.team_id WHERE public.staff_can_work(auth.uid(),i.id) AND i.duplicate_of IS NULL AND i.status::text NOT IN ('resolved','closed','rejected') GROUP BY coalesce(t.department,i.department,'Routing required'))s),'notification_failures',(SELECT count(*) FROM public.issue_notifications WHERE status='failed' AND public.staff_can_work(auth.uid(),issue_id)));
END $$;